    [4] = {
      beijing = 4990,
      dialog = 3,
      music = "PW_5_Suspect",
      renwu = "npc",
      sentence = "After being thrown out by Victor, I couldn't rest easy. I went around asking everyone in Pagoda Peace Village about how to become a tree guardian.",
