    [19] = {
      beijing = 1742,
      dialog = 3,
      music = "PW_0_title",
      renwu = "npc",
      sentence = "About a few hours later, I had excavated pretty much all the cordyceps on the mountain and found they all, without exception, were fed with a faint but steady Qi essence.",
