    },
    [38] = {
      beijing = 1742,
      dialog = 3,
      music = "PW_0_title",
      renwu = "npc",
      sentence = "Just then, I looked down and saw that the last patch of cordyceps seemed to have a layer of fresh soil covering it, and on the side, there was a bamboo shovel with bits of dirt stuck to it.",
